// 1. Two Pointers - tìm cặp phần tử có tổng bằng target trên mảng ĐÃ sắp xếp, O(n)
pair<int, int> twoSum(const vector<int>& a, int target) {
    int trai = 0, phai = (int)a.size() - 1;
    while (trai < phai) {
        int tong = a[trai] + a[phai];
        if (tong == target) return {trai, phai};
        if (tong < target) trai++;
        else phai--;
    }
    return {-1, -1};
}

// 2. Sliding Window - tổng lớn nhất của mảng con độ dài k, O(n)
int maxSubarraySum(const vector<int>& a, int k) {
    int tongCuaSo = 0;
    for (int i = 0; i < k; i++) tongCuaSo += a[i];
    int lonNhat = tongCuaSo;
    for (int i = k; i < (int)a.size(); i++) {
        tongCuaSo += a[i] - a[i - k]; // trượt cửa sổ sang phải
        lonNhat = max(lonNhat, tongCuaSo);
    }
    return lonNhat;
}

// 3. Bảng tần suất - ký tự xuất hiện nhiều nhất, O(n)
char kyTuNhieuNhat(const string& s) {
    unordered_map<char, int> dem;
    char kq = '\0';
    int nhieuNhat = 0;
    for (char c : s) {
        if (++dem[c] > nhieuNhat) {
            nhieuNhat = dem[c];
            kq = c;
        }
    }
    return kq;
}

// 4. Prefix Sum - tiền xử lý O(n), mỗi truy vấn tổng đoạn [i..j] chỉ O(1)
struct TongCongDon {
    vector<long long> p;
    explicit TongCongDon(const vector<int>& a) : p(a.size() + 1, 0) {
        for (size_t i = 0; i < a.size(); i++) p[i + 1] = p[i] + a[i];
    }
    long long tong(int i, int j) const { return p[j + 1] - p[i]; }
};


int main(){TongCongDon t({});cout<<t.p.size()<<" "<<t.p[0];}

